insert into kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, source, year, exam_body, stem, options, correct_option, explanation, lifecycle_state, distractor_rationale) values
($q$chemistry_0442$q$, $q$Chemistry$q$, $q$Separation of Mixtures$q$, $q$Separation Techniques$q$, $q$Answer a real JAMB 2008 question on Separation Techniques.$q$, $q$[{"conceptId": "kc1jua", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$medium$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Crystallization is used to obtain pure solids from a solution (like sugar from water), not to separate different colored pigments.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Hydrolysis is a chemical reaction involving water, not a physical separation technique.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Sublimation is only used when a solid can turn directly into a gas, like iodine or camphor; it won't help with plant pigments.", "misconceptionId": "memorized_not_understood"}]$q$::jsonb, $q$jamb_past_question$q$, 2008, $q$JAMB$q$, $q$Chlorophyll obtained from green leaves of plant can be shown to be composed of more than one coloured component by the technique of$q$, $q$[{"label": "A", "text": "crystallization", "isCorrect": false}, {"label": "B", "text": "hydrolysis", "isCorrect": false}, {"label": "C", "text": "chromatography", "isCorrect": true}, {"label": "D", "text": "sublimation", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Chromatography separates components of a mixture based on their different rates of movement across a material (like paper). Whenever you see a question about separating colours, pigments, or ink, chromatography should be your first thought.$q$, $q$live$q$, $q$A: Crystallization is used to obtain pure solids from a solution (like sugar from water), not to separate different colored pigments. B: Hydrolysis is a chemical reaction involving water, not a physical separation technique. D: Sublimation is only used when a solid can turn directly into a gas, like iodine or camphor; it won't help with plant pigments.$q$),
($q$chemistry_0443$q$, $q$Chemistry$q$, $q$Nature of Matter$q$, $q$Colligative Properties — Freezing Point Depression$q$, $q$Answer a real JAMB 2008 question on Colligative Properties — Freezing Point Depression.$q$, $q$[{"conceptId": "u7n0s9", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "While salt changes the density of the resulting saltwater, the goal of the process is to melt the ice, not change its weight.", "misconceptionId": "guessed_no_reasoning"}, {"option": "C", "explanation": "Adding salt does make the ice impure, but this is the mechanism, not the reason or purpose why we do it.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "If the melting point were raised, the ice would actually become harder and stay frozen longer, which is the opposite of what we want for safe roads.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2008, $q$JAMB$q$, $q$In countries where the temperature falls below 273K, salt is always sprinkled on the icy road in order to$q$, $q$[{"label": "A", "text": "lower the melting point of the ice", "isCorrect": true}, {"label": "B", "text": "increase the density of the ice", "isCorrect": false}, {"label": "C", "text": "make the ice impure", "isCorrect": false}, {"label": "D", "text": "raise the melting point of the ice", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Freezing point depression: pure water freezes at 273K. Adding salt (impurity) interferes with ice crystal formation, lowering the freezing point so ice melts even in cold weather.$q$, $q$live$q$, $q$B: While salt changes the density of the resulting saltwater, the goal of the process is to melt the ice, not change its weight. C: Adding salt does make the ice impure, but this is the mechanism, not the reason or purpose why we do it. D: If the melting point were raised, the ice would actually become harder and stay frozen longer, which is the opposite of what we want for safe roads.$q$),
($q$chemistry_0444$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Mass-Mass Stoichiometry$q$, $q$Answer a real JAMB 2008 question on Mass-Mass Stoichiometry.$q$, $q$[{"conceptId": "e5q9c8", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 72, $q$medium$q$, $q$heavy$q$, $q$[{"option": "A", "explanation": "This result usually comes from a decimal point error, likely moving it two places instead of one during the calculation.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "You might have correctly found the ratio but forgotten to account for the molar mass of NaOH correctly.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This result comes from ignoring the fact that 2.3g is a small fraction of the molar mass, essentially overestimating the yield by a factor of 2.", "misconceptionId": "rushed_under_pressure"}]$q$::jsonb, $q$jamb_past_question$q$, 2008, $q$JAMB$q$, $q$2Na(s) + 2H2O(l) -> 2NaOH(aq) + H2(g). From the equation above, calculate the mass of sodium hydroxide produced by 2.3g of sodium. [H = 1, O = 16, Na = 23]$q$, $q$[{"label": "A", "text": "0.40g", "isCorrect": false}, {"label": "B", "text": "0.80g", "isCorrect": false}, {"label": "C", "text": "4.00g", "isCorrect": true}, {"label": "D", "text": "8.00g", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Na=23, NaOH=40. 2 mol Na(46g) produces 2 mol NaOH(80g). 2.3g Na is 1/20 of 46g, so mass NaOH = 80/20 = 4.0g.$q$, $q$live$q$, $q$A: This result usually comes from a decimal point error, likely moving it two places instead of one during the calculation. B: You might have correctly found the ratio but forgotten to account for the molar mass of NaOH correctly. D: This result comes from ignoring the fact that 2.3g is a small fraction of the molar mass, essentially overestimating the yield by a factor of 2.$q$),
($q$chemistry_0445$q$, $q$Chemistry$q$, $q$Kinetic Theory & Gas Laws$q$, $q$Gas Laws$q$, $q$Answer a real JAMB 2008 question on Gas Laws.$q$, $q$[{"conceptId": "84csd7", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "You probably inverted the pressure ratio (300x650/800). Always remember: if pressure goes down, volume must go up!", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This looks like a double-up error in calculation, perhaps multiplying by 2 unnecessarily at the end.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This value is way too large; it suggests a major error in setting up the cross-multiplication for the P1V1 formula.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2008, $q$JAMB$q$, $q$300 cm3 of gas has a pressure of 800 mmHg. If the pressure is reduced to 650 mmHg, find its volume$q$, $q$[{"label": "A", "text": "243.75 cm3", "isCorrect": false}, {"label": "B", "text": "369.23 cm3", "isCorrect": true}, {"label": "C", "text": "738.46 cm3", "isCorrect": false}, {"label": "D", "text": "1733.36 cm3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$P1V1=P2V2. 300x800=650xV2. V2=240000/650=369.23 cm3.$q$, $q$live$q$, $q$A: You probably inverted the pressure ratio (300x650/800). Always remember: if pressure goes down, volume must go up! C: This looks like a double-up error in calculation, perhaps multiplying by 2 unnecessarily at the end. D: This value is way too large; it suggests a major error in setting up the cross-multiplication for the P1V1 formula.$q$),
($q$chemistry_0446$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$pH and pOH Calculations$q$, $q$Answer a real JAMB 2008 question on pH and pOH Calculations.$q$, $q$[{"conceptId": "8ocrzy", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 72, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "A pH of 14 would require a 1.0 M solution of NaOH. Our solution is 1000 times more dilute than that.", "misconceptionId": "guessed_no_reasoning"}, {"option": "B", "explanation": "This would be the pH of a 0.1 M solution (10^-1), not 0.001 M.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "This would be the pH of a 0.01 M solution (10^-2), not 0.001 M.", "misconceptionId": "rushed_under_pressure"}]$q$::jsonb, $q$jamb_past_question$q$, 2008, $q$JAMB$q$, $q$What is the pH of 0.001 mol dm-3 solution of sodium hydroxide?$q$, $q$[{"label": "A", "text": "14", "isCorrect": false}, {"label": "B", "text": "13", "isCorrect": false}, {"label": "C", "text": "12", "isCorrect": false}, {"label": "D", "text": "11", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$[OH-]=10^-3, pOH=3. pH=14-3=11.$q$, $q$live$q$, $q$A: A pH of 14 would require a 1.0 M solution of NaOH. Our solution is 1000 times more dilute than that. B: This would be the pH of a 0.1 M solution (10^-1), not 0.001 M. C: This would be the pH of a 0.01 M solution (10^-2), not 0.001 M.$q$),
($q$chemistry_0447$q$, $q$Chemistry$q$, $q$Energy Changes$q$, $q$Entropy and Disorder$q$, $q$Answer a real JAMB 2008 question on Entropy and Disorder.$q$, $q$[{"conceptId": "s55vck", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Entropy is only positive (increasing) when you go from solid to liquid/gas, or when you increase the number of gas molecules.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Entropy is never zero in a chemical reaction; there is always some change in the degree of disorder.", "misconceptionId": "memorized_not_understood"}, {"option": "D", "explanation": "This is a predictable system. Since two gas molecules produce one solid, the sign of the entropy change is definitely known to be negative.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2008, $q$JAMB$q$, $q$NH3(g) + HCl(g) -> NH4Cl(s). The entropy change in the system above is$q$, $q$[{"label": "A", "text": "positive", "isCorrect": false}, {"label": "B", "text": "zero", "isCorrect": false}, {"label": "C", "text": "negative", "isCorrect": true}, {"label": "D", "text": "indeterminate", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Two gases (high disorder) become one solid (low disorder), so entropy decreases: negative.$q$, $q$live$q$, $q$A: Entropy is only positive (increasing) when you go from solid to liquid/gas, or when you increase the number of gas molecules. B: Entropy is never zero in a chemical reaction; there is always some change in the degree of disorder. D: This is a predictable system. Since two gas molecules produce one solid, the sign of the entropy change is definitely known to be negative.$q$),
($q$chemistry_0448$q$, $q$Chemistry$q$, $q$Separation of Mixtures$q$, $q$Separation Techniques$q$, $q$Answer a real JAMB 2009 question on Separation Techniques.$q$, $q$[{"conceptId": "kc1jua", "weight": 1}]$q$::jsonb, 1, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "If you evaporate before filtering, you'll just end up with the same mixture of solid sugar and sulphur again. You must filter out the insoluble part first.", "misconceptionId": "rushed_under_pressure"}, {"option": "B", "explanation": "You can't filter a dry mixture of sugar and sulphur efficiently; they are both solids. You need to dissolve the sugar first.", "misconceptionId": "missing_prerequisite"}, {"option": "D", "explanation": "Evaporating first is pointless if there is no solvent yet. Always dissolve before trying to separate based on solubility.", "misconceptionId": "memorized_not_understood"}]$q$::jsonb, $q$jamb_past_question$q$, 2009, $q$JAMB$q$, $q$A mixture of sugar and sulphur can be separated by$q$, $q$[{"label": "A", "text": "dissolution in water, evaporation and filtration", "isCorrect": false}, {"label": "B", "text": "filtration, evaporation and dissolution in water", "isCorrect": false}, {"label": "C", "text": "dissolution in water, filtration and evaporation", "isCorrect": true}, {"label": "D", "text": "evaporation, dissolution in water and filtration", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Sugar dissolves in water, sulphur doesn't. Dissolve, filter out insoluble sulphur, then evaporate the filtrate to recover sugar.$q$, $q$live$q$, $q$A: If you evaporate before filtering, you'll just end up with the same mixture of solid sugar and sulphur again. You must filter out the insoluble part first. B: You can't filter a dry mixture of sugar and sulphur efficiently; they are both solids. You need to dissolve the sugar first. D: Evaporating first is pointless if there is no solvent yet. Always dissolve before trying to separate based on solubility.$q$),
($q$chemistry_0449$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Hydrates and Water of Crystallization$q$, $q$Answer a real JAMB 2009 question on Hydrates and Water of Crystallization.$q$, $q$[{"conceptId": "sdx4xa", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 72, $q$low$q$, $q$heavy$q$, $q$[{"option": "A", "explanation": "This error often occurs if you forget to multiply the water molecules by 7 or make an arithmetic slip during addition.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "You might have miscalculated the molar mass of the anhydrous salt, leading to an incorrect ratio.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This is an extremely high percentage and suggests you might have inverted the fraction or calculated the percentage of the metal instead.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2009, $q$JAMB$q$, $q$The percentage of water of crystallization in ZnSO4.7H2O is? [Zn = 65, S = 32, O = 16, H = 1]$q$, $q$[{"label": "A", "text": "33%", "isCorrect": false}, {"label": "B", "text": "44%", "isCorrect": true}, {"label": "C", "text": "55%", "isCorrect": false}, {"label": "D", "text": "87%", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Molar mass = 65+32+64+126=287g/mol. %water = 126/287x100=43.9% ~44%.$q$, $q$live$q$, $q$A: This error often occurs if you forget to multiply the water molecules by 7 or make an arithmetic slip during addition. C: You might have miscalculated the molar mass of the anhydrous salt, leading to an incorrect ratio. D: This is an extremely high percentage and suggests you might have inverted the fraction or calculated the percentage of the metal instead.$q$),
($q$chemistry_0450$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Stoichiometric Calculations — Gas Volumes$q$, $q$Answer a real JAMB 2009 question on Stoichiometric Calculations — Gas Volumes.$q$, $q$[{"conceptId": "v4o1jb", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 84, $q$medium$q$, $q$heavy$q$, $q$[{"option": "A", "explanation": "This looks like you accidentally used 0.01 moles instead of 0.0075. Always stick strictly to the mole values given in the question.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "You might have miscalculated the product of 0.0075x22.4 or used an incorrect molar volume.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This is a common round number guess, but it doesn't follow from the math of the equation.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2009, $q$JAMB$q$, $q$0.0075 mole of calcium trioxocarbonate (IV) is added to 0.015 mole of a solution of hydrochloric acid. The volume of gas evolved at s.t.p is? [Molar volume of a gas at s.t.p = 22.4 dm3]$q$, $q$[{"label": "A", "text": "224 cm3", "isCorrect": false}, {"label": "B", "text": "168 cm3", "isCorrect": true}, {"label": "C", "text": "112 cm3", "isCorrect": false}, {"label": "D", "text": "100 cm3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$CaCO3+2HCl->CaCl2+H2O+CO2, ratio 1:2. 0.0075 mol CaCO3 exactly matches 0.015 mol HCl. CO2 = 0.0075mol x 22.4 = 0.168dm3 = 168cm3.$q$, $q$live$q$, $q$A: This looks like you accidentally used 0.01 moles instead of 0.0075. Always stick strictly to the mole values given in the question. C: You might have miscalculated the product of 0.0075x22.4 or used an incorrect molar volume. D: This is a common round number guess, but it doesn't follow from the math of the equation.$q$),
($q$chemistry_0451$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Quantum Numbers$q$, $q$Answer a real JAMB 2009 question on Quantum Numbers.$q$, $q$[{"conceptId": "i5jfdn", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "The principal quantum number determines the main energy level (shell) itself, not its sub-divisions.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "The magnetic quantum number describes the orientation of an orbital in space (e.g. px,py,pz), a step deeper than identifying the orbital type.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "The spin quantum number only tells you the direction an electron is spinning within an orbital; it doesn't define the orbital itself.", "misconceptionId": "memorized_not_understood"}]$q$::jsonb, $q$jamb_past_question$q$, 2009, $q$JAMB$q$, $q$Which quantum number divides shells into orbitals?$q$, $q$[{"label": "A", "text": "principal", "isCorrect": false}, {"label": "B", "text": "Azimuthal", "isCorrect": true}, {"label": "C", "text": "Magnetic", "isCorrect": false}, {"label": "D", "text": "Spin", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Principal quantum number (n) gives the shell. Azimuthal (l) breaks shells into sub-shells/orbitals (s,p,d,f).$q$, $q$live$q$, $q$A: The principal quantum number determines the main energy level (shell) itself, not its sub-divisions. C: The magnetic quantum number describes the orientation of an orbital in space (e.g. px,py,pz), a step deeper than identifying the orbital type. D: The spin quantum number only tells you the direction an electron is spinning within an orbital; it doesn't define the orbital itself.$q$),
($q$chemistry_0452$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$Acidic and Basic Ions — Salt Hydrolysis$q$, $q$Answer a real JAMB 2009 question on Acidic and Basic Ions — Salt Hydrolysis.$q$, $q$[{"conceptId": "yzd6cv", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "An acidic salt only forms when you react a strong acid with a weak base. Here, the base is the strong one.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Complex salts involve dative bonding with transition metals. Sodium citrate is a simple organic salt.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "A salt is only neutral if both the acid and the base are strong (like HCl and NaOH). Citric acid is not a strong acid.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2009, $q$JAMB$q$, $q$The salt formed from a reaction between citric acid and sodium hydroxide in solution will be$q$, $q$[{"label": "A", "text": "acidic", "isCorrect": false}, {"label": "B", "text": "basic", "isCorrect": true}, {"label": "C", "text": "complex", "isCorrect": false}, {"label": "D", "text": "neutral", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$NaOH is a strong base, citric acid is a weak acid. Strong base wins the pH battle, giving a basic salt.$q$, $q$live$q$, $q$A: An acidic salt only forms when you react a strong acid with a weak base. Here, the base is the strong one. C: Complex salts involve dative bonding with transition metals. Sodium citrate is a simple organic salt. D: A salt is only neutral if both the acid and the base are strong (like HCl and NaOH). Citric acid is not a strong acid.$q$),
($q$chemistry_0453$q$, $q$Chemistry$q$, $q$Electrolysis$q$, $q$Electrolytic Purification of Metals$q$, $q$Answer a real JAMB 2009 question on Electrolytic Purification of Metals.$q$, $q$[{"conceptId": "qpxjys", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Zinc is typically purified by other means like distillation or chemical leaching after extraction.", "misconceptionId": "guessed_no_reasoning"}, {"option": "B", "explanation": "Iron is purified in a converter (like the Bessemer process) using oxygen to burn off impurities, not by electrolysis.", "misconceptionId": "memorized_not_understood"}, {"option": "C", "explanation": "Tin is usually purified by liquation or poling, which involve heating rather than electricity.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2009, $q$JAMB$q$, $q$Which of the following metals is purified commercially by electrolysis?$q$, $q$[{"label": "A", "text": "Zn", "isCorrect": false}, {"label": "B", "text": "Fe", "isCorrect": false}, {"label": "C", "text": "Sn", "isCorrect": false}, {"label": "D", "text": "Cu", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Copper is famously purified by electrolysis: impure copper anode, pure copper cathode, electrical energy moves pure copper to the cathode.$q$, $q$live$q$, $q$A: Zinc is typically purified by other means like distillation or chemical leaching after extraction. B: Iron is purified in a converter (like the Bessemer process) using oxygen to burn off impurities, not by electrolysis. C: Tin is usually purified by liquation or poling, which involve heating rather than electricity.$q$),
($q$chemistry_0454$q$, $q$Chemistry$q$, $q$Organic Chemistry$q$, $q$Hydrocarbons — Homologous Series$q$, $q$Answer a real JAMB 2009 question on Hydrocarbons — Homologous Series.$q$, $q$[{"conceptId": "r4t0dz", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Ethane only has 2 carbons. You can't have a branch with just two points!", "misconceptionId": "missing_prerequisite"}, {"option": "B", "explanation": "Ethene is an unsaturated straight-chain molecule. It doesn't have enough carbons for branching.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Propane has 3 carbons. Even if you try to bend it, it's still just one continuous line. You need that 4th carbon to create a fork.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2009, $q$JAMB$q$, $q$The simplest branched-chain hydrocarbon is$q$, $q$[{"label": "A", "text": "ethane", "isCorrect": false}, {"label": "B", "text": "ethene", "isCorrect": false}, {"label": "C", "text": "propane", "isCorrect": false}, {"label": "D", "text": "2-methylpropane", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$A branch needs at least 4 carbons. 2-methylpropane (isobutane) has 4 carbons with a center carbon attached to three others — the smallest branched molecule.$q$, $q$live$q$, $q$A: Ethane only has 2 carbons. You can't have a branch with just two points! B: Ethene is an unsaturated straight-chain molecule. It doesn't have enough carbons for branching. C: Propane has 3 carbons. Even if you try to bend it, it's still just one continuous line. You need that 4th carbon to create a fork.$q$),
($q$chemistry_0455$q$, $q$Chemistry$q$, $q$Nature of Matter$q$, $q$Mixtures vs Compounds$q$, $q$Answer a real JAMB 2010 question on Mixtures vs Compounds.$q$, $q$[{"conceptId": "h65avs", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Common salt is Sodium Chloride, which is a compound, not a mixture, because its elements are chemically bonded in a fixed ratio.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "In many exam contexts, sand is referred to as silica (SiO2), which is a chemical compound. Blood is a more obvious mixture of distinct components.", "misconceptionId": "memorized_not_understood"}, {"option": "D", "explanation": "Washing soda is a specific chemical compound (Sodium trioxocarbonate (IV) decahydrate), not a random mixture.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2010, $q$JAMB$q$, $q$Which of the following is an example of a mixture?$q$, $q$[{"label": "A", "text": "Common salt", "isCorrect": false}, {"label": "B", "text": "Blood", "isCorrect": true}, {"label": "C", "text": "Sand", "isCorrect": false}, {"label": "D", "text": "Washing soda", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Common salt and washing soda are compounds with fixed formulas. Sand is typically treated as pure silica (SiO2), a compound. Blood is a complex mixture of cells, proteins and salts separable by physical means.$q$, $q$live$q$, $q$A: Common salt is Sodium Chloride, which is a compound, not a mixture, because its elements are chemically bonded in a fixed ratio. C: In many exam contexts, sand is referred to as silica (SiO2), which is a chemical compound. Blood is a more obvious mixture of distinct components. D: Washing soda is a specific chemical compound (Sodium trioxocarbonate (IV) decahydrate), not a random mixture.$q$),
($q$chemistry_0456$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Percentage Composition$q$, $q$Answer a real JAMB 2010 question on Percentage Composition.$q$, $q$[{"conceptId": "naed66", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 72, $q$low$q$, $q$heavy$q$, $q$[{"option": "A", "explanation": "This result comes if you only count one Nitrogen atom (14/164) instead of two. Remember that Calcium has a valency of 2, so it needs two nitrate ions.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "This is a common arithmetic slip or a result of miscalculating the molar mass of the nitrate radical.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This value is too high and usually occurs if you ignore the Oxygen or Calcium mass during the final percentage step.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2010, $q$JAMB$q$, $q$Calculate the percentage by mass of nitrogen in calcium trioxonitrate (V) [Ca = 40, N = 14, O = 16]$q$, $q$[{"label": "A", "text": "8.5%", "isCorrect": false}, {"label": "B", "text": "13.1%", "isCorrect": false}, {"label": "C", "text": "17.1%", "isCorrect": true}, {"label": "D", "text": "27.6%", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Ca(NO3)2, molar mass=40+2(14+48)=164. 2N=28g. %N=28/164x100=17.1%.$q$, $q$live$q$, $q$A: This result comes if you only count one Nitrogen atom (14/164) instead of two. Remember that Calcium has a valency of 2, so it needs two nitrate ions. B: This is a common arithmetic slip or a result of miscalculating the molar mass of the nitrate radical. D: This value is too high and usually occurs if you ignore the Oxygen or Calcium mass during the final percentage step.$q$),
($q$chemistry_0457$q$, $q$Chemistry$q$, $q$Kinetic Theory & Gas Laws$q$, $q$Gas Laws$q$, $q$Answer a real JAMB 2010 question on Gas Laws.$q$, $q$[{"conceptId": "84csd7", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "You might be thinking of a squared relationship, but Boyle's Law is a simple inverse linear relationship.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "This is the most common trap! You applied the 'half' to the volume instead of realizing they move in opposite directions. Less pressure means more room for the gas to expand.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This suggests the pressure change had no effect, which contradicts the kinetic theory of gases.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2010, $q$JAMB$q$, $q$The volume of a given gas is V cm3 at a pressure P mm Hg. What is the new volume of the gas if the pressure is reduced to half at constant temperature?$q$, $q$[{"label": "A", "text": "4 V cm3", "isCorrect": false}, {"label": "B", "text": "2 V cm3", "isCorrect": true}, {"label": "C", "text": "V/2 cm3", "isCorrect": false}, {"label": "D", "text": "V cm3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$P1V1=P2V2. Halving pressure means volume must double: 2V.$q$, $q$live$q$, $q$A: You might be thinking of a squared relationship, but Boyle's Law is a simple inverse linear relationship. C: This is the most common trap! You applied the 'half' to the volume instead of realizing they move in opposite directions. Less pressure means more room for the gas to expand. D: This suggests the pressure change had no effect, which contradicts the kinetic theory of gases.$q$),
($q$chemistry_0458$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Electronic Configuration and Periodic Blocks$q$, $q$Answer a real JAMB 2010 question on Electronic Configuration and Periodic Blocks.$q$, $q$[{"conceptId": "7u41s5", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "You might have tried to pair two electrons in one p orbital, leaving only one unpaired, but Hund's Rule forbids pairing until each orbital has one electron.", "misconceptionId": "memorized_not_understood"}, {"option": "C", "explanation": "This happens if you assume only the last electron is unpaired, forgetting the single-occupancy rule for p orbitals.", "misconceptionId": "missing_prerequisite"}, {"option": "D", "explanation": "This would mean all electrons are paired, which is characteristic of noble gases like Neon, not Nitrogen.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2010, $q$JAMB$q$, $q$How many unpaired electron(s) are there in the nitrogen sub-levels?$q$, $q$[{"label": "A", "text": "3", "isCorrect": true}, {"label": "B", "text": "2", "isCorrect": false}, {"label": "C", "text": "1", "isCorrect": false}, {"label": "D", "text": "none", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$N: 1s2 2s2 2p3. Hund's Rule: the three 2p electrons each occupy their own orbital singly, giving 3 unpaired electrons.$q$, $q$live$q$, $q$B: You might have tried to pair two electrons in one p orbital, leaving only one unpaired, but Hund's Rule forbids pairing until each orbital has one electron. C: This happens if you assume only the last electron is unpaired, forgetting the single-occupancy rule for p orbitals. D: This would mean all electrons are paired, which is characteristic of noble gases like Neon, not Nitrogen.$q$),
($q$chemistry_0459$q$, $q$Chemistry$q$, $q$Acids, Bases & Salts$q$, $q$Titration Calculations$q$, $q$Answer a real JAMB 2010 question on Titration Calculations.$q$, $q$[{"conceptId": "e6pk77", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 72, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "This result comes if you forget the 1:2 mole ratio and assume it is 1:1. Always check if the acid is diprotic like H2SO4!", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This is likely a result of inverting the concentration values in the formula.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This is a significant arithmetic error, possibly from a decimal point slip during the division.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 2010, $q$JAMB$q$, $q$Calculate the volume of 0.5 mol dm-3 H2SO4 that is neutralized by 25 cm3 of 0.1 mol dm-3 NaOH?$q$, $q$[{"label": "A", "text": "5.0 cm3", "isCorrect": false}, {"label": "B", "text": "2.5 cm3", "isCorrect": true}, {"label": "C", "text": "0.4 cm3", "isCorrect": false}, {"label": "D", "text": "0.1 cm3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$H2SO4+2NaOH->Na2SO4+2H2O, ratio na=1,nb=2. CaVa/na=CbVb/nb: 0.5Va/1=(0.1x25)/2=1.25. Va=2.5cm3.$q$, $q$live$q$, $q$A: This result comes if you forget the 1:2 mole ratio and assume it is 1:1. Always check if the acid is diprotic like H2SO4! C: This is likely a result of inverting the concentration values in the formula. D: This is a significant arithmetic error, possibly from a decimal point slip during the division.$q$),
($q$chemistry_0460$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Intermolecular Forces — Van der Waals$q$, $q$Answer a real JAMB 2010 question on Intermolecular Forces — Van der Waals.$q$, $q$[{"conceptId": "zxcqb1", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This incorrectly puts the alcohol as the lowest. Remember, hydrogen bonds in alcohols are much harder to break than the weak forces in alkanes.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "This order is almost completely backwards. It assumes longer alkanes have higher boiling points than alcohols, which is usually not true for these molecular weights.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "While you correctly started with the shortest alkane, you underestimated the strength of the hydrogen bond in propanol compared to the Van der Waals forces in heptane.", "misconceptionId": "memorized_not_understood"}]$q$::jsonb, $q$jamb_past_question$q$, 2010, $q$JAMB$q$, $q$The correct order of increasing boiling points of the following compounds C3H7OH, C7H16 and C4H10 is?$q$, $q$[{"label": "A", "text": "C3H7OH -> C4H10 -> C7H16", "isCorrect": false}, {"label": "B", "text": "C4H10 -> C7H16 -> C3H7OH", "isCorrect": true}, {"label": "C", "text": "C7H16 -> C3H7OH -> C4H10", "isCorrect": false}, {"label": "D", "text": "C4H10 -> C3H7OH -> C7H16", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Propanol has hydrogen bonding, giving it the highest boiling point. Between the alkanes, the longer chain (C7) has more Van der Waals forces than the shorter (C4). Order: C4 < C7 < alcohol.$q$, $q$live$q$, $q$A: This incorrectly puts the alcohol as the lowest. Remember, hydrogen bonds in alcohols are much harder to break than the weak forces in alkanes. C: This order is almost completely backwards. It assumes longer alkanes have higher boiling points than alcohols, which is usually not true for these molecular weights. D: While you correctly started with the shortest alkane, you underestimated the strength of the hydrogen bond in propanol compared to the Van der Waals forces in heptane.$q$);
